ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	vehicle: payload.vehicle map (data, index)->{
		vin: data.vin,
		stockNumber: data.stockNumber
	},
	dealerNumber: payload.dealerNumber,
	stickerName: payload.stickerName
}

ee:variables.ee:set-variable:
%dw 2.0
var fileName = vars.stickerName
var fileNameArr = fileName splitBy ","
var title_name2 = ""
output application/java
---
(fileNameArr map(
if($ == "BuyersGuide")
				title_name2 ++ "_BG"				
			else if($ == "VehicleDetails")
				title_name2 ++ "_VD"
			else if($ == "VehicleTitle")
				title_name2 ++ "_VT"
			else if($ == "VehicleBrochure")
				title_name2 ++ "_VB"
			else if($ == "BuyersGuideSpanish")
				title_name2 ++ "_SBG"
            else ""			
   )) joinBy ""

%dw 2.0
output application/java
---
(if ( vars.optionsFields.EXTERIOR != null ) (vars.optionsFields.EXTERIOR map {
	'type': "exterior",
	description: $
}) else []) ++

(if ( vars.optionsFields.INTERIOR != null ) (vars.optionsFields.INTERIOR map {
	'type': "interior",
	description: $
})  else []) ++

(if ( vars.optionsFields.SAFETY != null ) (vars.optionsFields.SAFETY map {
	'type': "safety",
	description: $
})  else []) ++

(if ( vars.optionsFields.ADDITIONAL != null ) (vars.optionsFields.ADDITIONAL map {
	'type': "additional",
	description: $
})  else []) ++

(if ( vars.optionsFields.ENG != null ) (vars.optionsFields.ENG map {
	'type': "eng",
	description: $
}) else  [])

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	inventoryPayload: if ( vars.aggregator != [] ) vars.aggregator else payload
}
